INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38211, 'Jeremiah 39:12', 'Jeremiah', 39, 12, '”لاړ شئ او يرمياه پېدا کړئ او د هغۀ ښۀ خيال وساتئ. هغۀ له تکليف مۀ ورکوئ او هغه چې څۀ غواړى هغه ورله وکړئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_12.mp3', '', 1761754199, 1761754199),
(38212, 'Jeremiah 39:13', 'Jeremiah', 39, 13, 'نو نبوزردان فوجى کمانډر، نبو‌شازبان مشر آفسر، نرګل‌شراضر د بادشاه مشاور، او د بابل بادشاه نورو ټولو آفسرانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_13.mp3', '', 1761754199, 1761754199),
(38213, 'Jeremiah 39:14', 'Jeremiah', 39, 14, 'حکم وکړو چې يرمياه د فوجيانو چاوڼۍ نه رابهر کړئ. هغوئ هغه جدلياه د اخيقام زوئ او د سافن نمسى ته وسپارلو، چا چې هغه خپل کور ته واپس بوتلو. نو بيا هغه په يهوداه کښې د خپلو خلقو سره پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_14.mp3', '', 1761754199, 1761754199),
(38214, 'Jeremiah 39:15', 'Jeremiah', 39, 15, 'په کوم وخت کښې چې يرمياه په فوجى چاوڼۍ کښې بند وو، نو د مالِک خُدائ کلام په هغۀ نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_15.mp3', '', 1761754199, 1761754199),
(38215, 'Jeremiah 39:16', 'Jeremiah', 39, 16, '”لاړ شئ او د ايتهوپيا عبيدمَلِک ته ووايئ چې مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به د دې ښار سره هر هغه څۀ وکړم لکه څنګه چې ما هغوئ ته دهمکى ورکړې ده. زۀ به په هغوئ باندې افتونه نازل کړم، نه چې آبادى. تۀ به د هغوئ تباهى وګورې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_16.mp3', '', 1761754199, 1761754199),
(38216, 'Jeremiah 39:17', 'Jeremiah', 39, 17, 'خو په هغه ورځ به زۀ تا بچ کړم او تۀ به هغه چا ته حواله نۀ کړے شې د چا نه چې ستا په زړۀ کښې يره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_17.mp3', '', 1761754199, 1761754199),
(38217, 'Jeremiah 39:18', 'Jeremiah', 39, 18, 'ځکه چې تا په ما باور وکړو، زۀ به ستا ژوند تا ته درکړم. زۀ به تا بچ کړم او محفوظ به دې وساتم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_18.mp3', '', 1761754199, 1761754199),
(38218, 'Exodus 30:1', 'Exodus', 30, 1, 'د خوشبویۍ د سوځولو دپاره د اکاسۍ د لرګي څخه د قربانۍ ځای جوړ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_1.mp3', '', 1761754199, 1761754199),
(38219, 'Exodus 30:2', 'Exodus', 30, 2, 'هغه باید څلور کنجه وي. پنځه څلوېښت سانتي باید اوږد وي او پنځه څلوېښت سانتي پلن او نوي سانتي باید لوړ وي. د هغه ښکرونه چې په څلورو کنجونو کې دي، هغه دې د قربانۍ د ځای سره د یوې ټوټې لرګي څخه جوړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_2.mp3', '', 1761754199, 1761754199),
(38220, 'Exodus 30:3', 'Exodus', 30, 3, 'د هغه پاسنۍ برخې، څلور واړه خواو او ښکرونو ته د سرو زرو پوښ ورکړه او ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_3.mp3', '', 1761754199, 1761754199),
(38221, 'Exodus 30:4', 'Exodus', 30, 4, 'د څنډو لاندې د قربانۍ د ځای دپاره دوه د سرو زرو کړۍ ګانې جوړې کړه، یعنې په دواړو خواو باندې یې یوه یوه جوړه کړه چې هغه میلې ونیسي چې د هغې په وړلو کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_4.mp3', '', 1761754199, 1761754199),
(38222, 'Exodus 30:5', 'Exodus', 30, 5, 'میلې د اکاسۍ د لرګي څخه جوړې کړه او د سرو زرو پوښ ورته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_5.mp3', '', 1761754199, 1761754199),
(38223, 'Exodus 30:6', 'Exodus', 30, 6, 'د قربانۍ ځای د هغې پردې مخې ته کېږده چې د لوظ د صندوق په مخکې ده، یعنې د هغه سرپوښ مخې ته چې د لوظ په صندوق باندې پروت دی. په هغه ځای کې به زه ستا سره لیدنه کتنه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_6.mp3', '', 1761754199, 1761754199),
(38224, 'Exodus 30:7', 'Exodus', 30, 7, 'هر سهار کله چې هارون د څراغونو د تیارولو دپاره راځي، په هغې باندې دې خوشبویي وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_7.mp3', '', 1761754199, 1761754199),
(38225, 'Exodus 30:8', 'Exodus', 30, 8, 'کله چې هغه په ماښام کې څراغونه لګوي، باید همداسې وکړي. دغه د خوشبویۍ نذرانه دې پرته له کوم ځنډه تل ترتله جاري وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_8.mp3', '', 1761754199, 1761754199),
(38226, 'Exodus 30:9', 'Exodus', 30, 9, 'د قربانۍ په دې ځای باندې هېڅ حرامه خوشبویي یا کومه سوځېدونکې نذرانه یا د غلې دانې نذرانه مه وړاندې کوئ او په هغې باندې د څښلو نذرانه مه اچوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_9.mp3', '', 1761754199, 1761754199),
(38227, 'Exodus 30:10', 'Exodus', 30, 10, 'په کال کې دې یوځل هارون د قربانۍ د ځای د پاکولو دپاره په څلورو ښکرونو باندې د هغه حیوان د وینې د سولولو مراسم سرته ورسوي کوم چې د ګناه دپاره قرباني کیږي. دا کار دې تل ترتله هر کال تر سره شي. دغه د قربانۍ ځای دې په پوره توګه سپېڅلی شي او ما یعنې څښتن ته دې وقف شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_10.mp3', '', 1761754199, 1761754199),
(38228, 'Exodus 30:11', 'Exodus', 30, 11, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_11.mp3', '', 1761754199, 1761754199),
(38229, 'Exodus 30:12', 'Exodus', 30, 12, '«کله چې ته د اسراییلیانو سرشمېرنه کوې، هر یو باید څښتن ته د شمېرلو په وخت کې د خپل ژوند په خاطر بیه ادا کړي. بیا چې کله هغوی شمېرې، هېڅ بلا به په هغوی باندې نازله نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_12.mp3', '', 1761754199, 1761754199),
(38230, 'Exodus 30:13', 'Exodus', 30, 13, 'هر یو تن چې په سرشمېرنه کې شاملیږي، هغه دې د هغه مثقال له مخې چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي او شپږ ګرامه وزن ولري، یو مثقال ورکړي. دغه یو مثقال ماته یوه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_13.mp3', '', 1761754199, 1761754199),
(38231, 'Exodus 30:14', 'Exodus', 30, 14, 'هر یو تن چې په سرشمېرنه کې شمېرل کیږي، یعنې هر یو سړی چې عمر یې شل کاله یا د شلو کالو څخه زیات وي، هغه دې دا نذرانه څښتن ته ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_14.mp3', '', 1761754199, 1761754199),
(38232, 'Exodus 30:15', 'Exodus', 30, 15, 'کله چې تاسو څښتن ته نذرانه وړاندې کوئ چې د خپل ژوند دپاره کفاره ادا کړئ، نو څوک چې شتمن وي هغه دې د یوې سکې څخه زیات نه ورکوي او څوک چې غریب وي هغه دې د یوې سکې څخه کم نه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_15.mp3', '', 1761754199, 1761754199),
(38233, 'Exodus 30:16', 'Exodus', 30, 16, 'د اسراییلو د خلکو څخه د دغې کفارې پیسې راټولې کړه او د سپېڅلې خېمې په ساتنه او څارنه کې یې مصرف کړه. دا پیسې به د هغوی د ژوند په خاطر کفاره وي او زه به هغوی رایادوم چې ویې ساتم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_16.mp3', '', 1761754199, 1761754199),
(38234, 'Exodus 30:17', 'Exodus', 30, 17, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_17.mp3', '', 1761754199, 1761754199),
(38235, 'Exodus 30:18', 'Exodus', 30, 18, '«د وینځلو دپاره د برنجو یو تشت جوړ کړه چې برنجي پایې ولري. هغه د سپېڅلې خېمې او د قربانۍ د ځای ترمنځ کېږده او اوبه په کې واچوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_18.mp3', '', 1761754199, 1761754199),
(38236, 'Exodus 30:19', 'Exodus', 30, 19, 'هارون او د هغه زامن دې د هغه څخه اوبه واخلي او خپل لاسونه او پښې دې ووینځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_19.mp3', '', 1761754199, 1761754199),
(38237, 'Exodus 30:20', 'Exodus', 30, 20, 'هرکله چې هغوی سپېڅلې خېمې ته ورننوځي، نو خپل لاسونه او پښې به وینځي، ترڅو مړه نه شي. همدارنګه کله چې هغوی د قربانۍ ځای ته ورنژدې کیږي چې ماته په اور باندې یوه نذرانه وړاندې کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_20.mp3', '', 1761754199, 1761754199),
(38238, 'Exodus 30:21', 'Exodus', 30, 21, 'نو هغوی باید خپل لاسونه او پښې ووینځي، ترڅو مړه نه شي. دا یو حکم دی چې هارون او د هغه اولاده باید د تل دپاره د هغه څخه پیروي وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_21.mp3', '', 1761754199, 1761754199),
(38239, 'Exodus 30:22', 'Exodus', 30, 22, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_22.mp3', '', 1761754199, 1761754199),
(38240, 'Exodus 30:23', 'Exodus', 30, 23, '«دا لاندېنۍ ښې مسالې واخله: شپږ کیلو ګرامه د مر کنډ چې د مایع په شکل وي، درې کیلو ګرامه خوشبویه دالچیني، درې کیلو ګرامه خوشبویه باڼس،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_23.mp3', '', 1761754199, 1761754199),
(38241, 'Exodus 30:24', 'Exodus', 30, 24, 'شپږ کیلو ګرامه د سناد د پاڼو شیره، (ټول دې د هغه وزن له مخې وي چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي) او څلور لیتره د زیتونو تېل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_24.mp3', '', 1761754199, 1761754199),
(38242, 'Exodus 30:25', 'Exodus', 30, 25, 'له هغو څخه د مسح کولو سپېڅلي تېل جوړ کړه. دا دې د عطرو په شان یو مخلوط وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_25.mp3', '', 1761754199, 1761754199),
(38243, 'Exodus 30:26', 'Exodus', 30, 26, 'بیا د دغو شیانو په مسح کولو کې ورڅخه کار واخله: سپېڅلې خېمه او د لوظ صندوق،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_26.mp3', '', 1761754199, 1761754199),
(38244, 'Exodus 30:27', 'Exodus', 30, 27, 'مېز او د هغه ټول سامان، څراغدان او د هغه سامان، د خوشبویۍ د سوځولو د قربانۍ ځای،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_27.mp3', '', 1761754199, 1761754199),
(38245, 'Exodus 30:28', 'Exodus', 30, 28, 'د سوځېدونکې نذرانې د قربانۍ ځای او د هغه ټول لوښي او تشت د هغه د پایو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_28.mp3', '', 1761754199, 1761754199),
(38246, 'Exodus 30:29', 'Exodus', 30, 29, 'په دې ډول دغه شیان وقف کړه او هغه به دومره سپېڅلي شي چې هرڅوک یا هر شی د هغو سره ولګیږي، نو هغه به هم سپېڅلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_29.mp3', '', 1761754199, 1761754199),
(38247, 'Exodus 30:30', 'Exodus', 30, 30, 'هارون او د هغه زامن مسح کړه او وقف کړه، ترڅو هغوی د کاهنانو په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_30.mp3', '', 1761754199, 1761754199),
(38248, 'Exodus 30:31', 'Exodus', 30, 31, 'اسراییلیانو ته داسې ووایه: دا د مسح کولو سپېڅلي تېل به تل ترتله زما د خدمت دپاره کارول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_31.mp3', '', 1761754199, 1761754199),
(38249, 'Exodus 30:32', 'Exodus', 30, 32, 'هغه د عادي خلکو په بدنونو باندې مه تویوئ او د داسې ترکیب څخه هېڅ تېل مه جوړوئ. هغه پاک دي او تاسو یې باید پاک وګڼئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_32.mp3', '', 1761754199, 1761754199),
(38250, 'Exodus 30:33', 'Exodus', 30, 33, 'هرڅوک چې دا ډول عطر جوړ کړي او هرڅوک چې هغه پرته له کاهنه په بل چا باندې وسولوي باید زما د قوم څخه وشړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_33.mp3', '', 1761754199, 1761754199),
(38251, 'Exodus 30:34', 'Exodus', 30, 34, 'بیا څښتن موسی ته وویل: «دغه خوشبویه مسالې واخله لکه کنډ، خوشبویه صدف او سوچه او قیمتي خوشبویي. دا ټول دې په یوه اندازه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_34.mp3', '', 1761754199, 1761754199),
(38252, 'Exodus 30:35', 'Exodus', 30, 35, 'د خوشبویۍ د جوړولو دپاره د هغو څخه کار واخله او د عطرو په شان یو مخلوط جوړ کړه. په هغو کې مالګه ورزیاته کړه چې هغه سوچه او پاکه وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_35.mp3', '', 1761754199, 1761754199),
(38253, 'Exodus 30:36', 'Exodus', 30, 36, 'له هغې څخه لږ د پوډرو په شان میده میده کړه او په سپېڅلې خېمه کې یې د لوظ د صندوق مخې ته په هغه ځای کې کېږده چې زه درسره لیدنه او کتنه کوم. هغه به تاسو ته ډېره سپېڅلې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_36.mp3', '', 1761754199, 1761754199),
(38254, 'Exodus 30:37', 'Exodus', 30, 37, 'د خپلو ځانونو دپاره له دې ترکیب څخه هېڅ خوشبویي مه جوړوئ. هغه زما څښتن په خاطر سپېڅلې وګڼئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_37.mp3', '', 1761754199, 1761754199),
(38255, 'Exodus 30:38', 'Exodus', 30, 38, 'هرڅوک چې داسې یو شی جوړ کړي چې د خوشبویۍ څخه یې خوند واخلي، باید زما له قوم څخه وشړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus30_verse_38.mp3', '', 1761754199, 1761754199),
(38256, 'Psalms 39:1', 'Psalms', 39, 1, 'ما د ځانه سره وویل: «څه چې کړمه په هغه کې به احتیاط کړم خپله ژبه به پرېنږدم چې ګناه راباندې وکړي د بدکارانو خلکو مخکې به زه هېڅ نه وایم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_1.mp3', '', 1761754199, 1761754199),
(38257, 'Psalms 39:2', 'Psalms', 39, 2, 'هېڅ خبره مې ونه کړه زه خاموش پاتې شوم زه وم خاموش حتی د ښو شیانو ذکر مې هم نه کولو خو پرېشاني مې نوره هم زیاته شوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_2.mp3', '', 1761754199, 1761754199),
(38258, 'Psalms 39:3', 'Psalms', 39, 3, 'زړګی مې ډک د پرېشانۍ ځینې شو څومره ژور فکر چې ما به کاوه راباندې اور لګېده ترڅو اخر مې وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_3.mp3', '', 1761754199, 1761754199),
(38259, 'Psalms 39:4', 'Psalms', 39, 4, '«زه به ترڅو یمه ژوندی څښتنه او زه به کله مرمه؟ راته ووایه چې ژوند به زما څنګه زر شي ختم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_4.mp3', '', 1761754199, 1761754199),
(38260, 'Psalms 39:5', 'Psalms', 39, 5, 'تا زما د ژوند نه مازدیګر د ژمي جوړ کړ نه دی هېڅ شی ستا نظر کې زما ژوندون ژوند د انسان دی په رښتیا لکه پوکي په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_5.mp3', '', 1761754199, 1761754199),
(38261, 'Psalms 39:6', 'Psalms', 39, 6, 'په رښتیا د انسان ژوند لکه سیوری پناه کیږي په رښتیا چې دی زحمت وباسي هغه بېځایه دی ټول راټولوي دولت خو نه پوهیږي چاته پاتې کیږي به ترې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_6.mp3', '', 1761754199, 1761754199),
(38262, 'Psalms 39:7', 'Psalms', 39, 7, 'نو ای څښتنه، بیا د څه امید کولای شمه؟ دی توکل زما په تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_7.mp3', '', 1761754199, 1761754199),
(38263, 'Psalms 39:8', 'Psalms', 39, 8, 'خپلو ټولو ګناهونو نه مې خلاص کړه کم‌عقلان مه پرېږده خندا وکړي په ما پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_8.mp3', '', 1761754199, 1761754199),
(38264, 'Psalms 39:9', 'Psalms', 39, 9, 'زه وم خاموش او هېڅ مې نه ویله ځکه چې تا راباندې دارنګه عذاب راوستلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_9.mp3', '', 1761754199, 1761754199),
(38265, 'Psalms 39:10', 'Psalms', 39, 10, 'نور مې مه ځوروه ډېر دې ځورولی یمه زه ستا په وهلو باندې ډېر ضعیفه شوی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_10.mp3', '', 1761754199, 1761754199),
(38266, 'Psalms 39:11', 'Psalms', 39, 11, 'په سبب زمونږ د خپلو ګناهونو راکوې سزا ته مونږ ته په رټلو هغه څه چې خوښوو مونږ هغه ته بربادوې لکه حشرې په شان په رښتیا چې مونږ پوکی یو بل څه نه یو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_11.mp3', '', 1761754199, 1761754199),
(38267, 'Psalms 39:12', 'Psalms', 39, 12, 'ای څښتنه، ته دعا واوره زما غوږ دې ونیسه فریاد ته ته زما هغه وخت چې زه ژړا کړم نو کومک لره مې راشه زه د څو شېبو دپاره ستا مېلمه یم لکه څنګه چې نیکونه وو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_12.mp3', '', 1761754199, 1761754199),
(38268, 'Psalms 39:13', 'Psalms', 39, 13, 'مخکې له دې نه چې زه مړ شم او نور پاتې نه شم یوازې پرېږده ما ترڅو چې لږ خوشحاله شمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms39_verse_13.mp3', '', 1761754199, 1761754199),
(38269, 'Numbers 25:1', 'Numbers', 25, 1, 'کله چې اسراییلیان په شطیم کې اوسېدل، ځینو سړیو د موآبي ښځو سره زنا کول پیل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_1.mp3', '', 1761754199, 1761754199),
(38270, 'Numbers 25:2', 'Numbers', 25, 2, 'دغو ښځو بیا هغه سړي هغو مراسمو ته راوبلل چې د هغوی خدایانو ته په کې نذرانې وړاندې کېدلې. د اسراییلو خلکو د قربانیو غوښه وخوړله او د موآبي خدایانو عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_2.mp3', '', 1761754199, 1761754199),
(38271, 'Numbers 25:3', 'Numbers', 25, 3, 'څښتن په اسراییلیانو باندې په قهر شو، ځکه چې هغوی د بعل فغور د بت عبادت کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_3.mp3', '', 1761754199, 1761754199),
(38272, 'Numbers 25:4', 'Numbers', 25, 4, 'نو هغه موسی ته وویل: «د اسراییلو ټول مشران بوځه او په رڼا ورځ یې زما په حضور کې اعدام کړه، بیا به زما سخت قهر په اسراییلیانو باندې سوړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_4.mp3', '', 1761754199, 1761754199),
(38273, 'Numbers 25:5', 'Numbers', 25, 5, 'موسی هغو اسراییلیانو ته چې د قاضیانو په توګه یې کار کاوه وویل: «تاسو هر یو باید د خپلې قبیلې هغه کس ووژنئ چې د بعل فغور عبادت یې کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_5.mp3', '', 1761754199, 1761754199),
(38274, 'Numbers 25:6', 'Numbers', 25, 6, 'یو اسراییلي سړي د موسی او ټول قوم په مخکې چې هغوی د سپېڅلې خېمې په دروازه کې ژړل، یوه مدیانۍ ښځه خپلې خېمې ته راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_6.mp3', '', 1761754199, 1761754199),
(38275, 'Numbers 25:7', 'Numbers', 25, 7, 'د العازار زوی او د هارون کاهن لمسي فینحاس هغه ولیدل او د خلکو د ګڼې ګوڼې څخه لاړ. هغه یوه نېزه راواخیستله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_7.mp3', '', 1761754199, 1761754199),
(38276, 'Numbers 25:8', 'Numbers', 25, 8, 'او د هغه سړي پسې خېمې ته ورننوت او د هغه په بدن او د ښځې په ګېډه کې یې ومنډله. په دې ډول څښتن هغه وبا بنده کړه چې اسراییلیان یې له منځه وړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_8.mp3', '', 1761754199, 1761754199),
(38277, 'Numbers 25:9', 'Numbers', 25, 9, 'خو وبا لا له مخکې څخه ۲۴۰۰۰ کسان وژلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_9.mp3', '', 1761754199, 1761754199),
(38278, 'Numbers 25:10', 'Numbers', 25, 10, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_10.mp3', '', 1761754199, 1761754199),
(38279, 'Numbers 25:11', 'Numbers', 25, 11, '«فینحاس د العازار زوی او د هارون کاهن لمسي زما قهر چې په اسراییلو باندې راغلی ؤ، سوړ کړ. هغه په ما باندې غیرت وکړ، نو په دې خاطر مې هغوی تباه نه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_11.mp3', '', 1761754199, 1761754199),
(38280, 'Numbers 25:12', 'Numbers', 25, 12, 'نو ورته ووایه چې زه د هغه سره د سولې داسې لوظ کوم چې د تل دپاره به اعتبار ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_12.mp3', '', 1761754199, 1761754199),
(38281, 'Numbers 25:13', 'Numbers', 25, 13, 'هغه او د هغه اولاده به د تل دپاره زما کاهنان وي، ځکه چې هغه د خپل خدای د عزت دپاره غیرت وکړ او د اسراییلیانو دپاره یې کفاره ادا کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_13.mp3', '', 1761754199, 1761754199),
(38282, 'Numbers 25:14', 'Numbers', 25, 14, 'د هغه اسراییلي نوم چې د مدیانۍ ښځې سره ووژل شو، د سالو زوی زیمري ؤ او هغه د شمعون د قبیلې یو مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_14.mp3', '', 1761754199, 1761754199),
(38283, 'Numbers 25:15', 'Numbers', 25, 15, 'د ښځې نوم کزبي ؤ. د هغې پلار صور د مدیانیانو د طایفو یو مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_15.mp3', '', 1761754199, 1761754199),
(38284, 'Numbers 25:16', 'Numbers', 25, 16, 'څښتن موسی ته حکم وکړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_16.mp3', '', 1761754199, 1761754199),
(38285, 'Numbers 25:17', 'Numbers', 25, 17, '«په مدیانیانو باندې حمله وکړه او هغوی ووژنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_17.mp3', '', 1761754199, 1761754199),
(38286, 'Numbers 25:18', 'Numbers', 25, 18, 'دا د هغه بد کار له امله چې ستاسو سره یې وکړ چې په فغور کې یې وغولولئ چې بعل فغور ته عبادت وکړئ او د کزبي له امله چې د یو مدیاني مشر لور وه او په فغور کې د وبا په وخت کې ووژل شوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers25_verse_18.mp3', '', 1761754199, 1761754199),
(38287, 'Hosea 1:1', 'Hosea', 1, 1, 'دا هغه پیغام دی چې څښتن د بیري زوی هوشع ته په هغه وخت کې ورکړی ؤ چې عزیا، یوتام، آحاز او حزقیا د یهودا پاچاهان وو او د یهوآش زوی یروبعام د اسراییلو پاچا ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_1.mp3', '', 1761754199, 1761754199),
(38288, 'Hosea 1:2', 'Hosea', 1, 2, 'کله چې څښتن د لومړي ځل دپاره د هوشع په وسیله د اسراییلو سره خبرې وکړې، هغه وویل: «لاړ شه او د یوې ښځې سره واده وکړه او هغه به یوه بې‌وفا ښځه وي او ستا اولادونه به هم د هغې په شان وي. په همدې ډول زما قوم هم بې‌وفا شوی دی او زه یې پریښی یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_2.mp3', '', 1761754199, 1761754199),
(38289, 'Hosea 1:3', 'Hosea', 1, 3, 'نو هوشع د یوې ښځې سره چې نوم یې جومر ؤ او د دبلایم لور وه، واده وکړ. هغه امیدواره شوه او زوی یې پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_3.mp3', '', 1761754199, 1761754199),
(38290, 'Hosea 1:4', 'Hosea', 1, 4, 'نو څښتن هوشع ته وویل: «په هغه باندې یزرعیل نوم کېږده، ځکه چې زه به ډېر زر د اسراییلو پاچا ته د هغو قتلونو په خاطر سزا ورکړم چې د هغه نیکه ییهو پاچا په یزرعیل کې کړي دي. زه به د اسراییلو شاهي خاندان له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_4.mp3', '', 1761754199, 1761754199),
(38291, 'Hosea 1:5', 'Hosea', 1, 5, 'په هغه ورځ به زه د یزرعیل په دره کې د اسراییلو نظامي قدرت له منځه یوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_5.mp3', '', 1761754199, 1761754199),
(38292, 'Hosea 1:6', 'Hosea', 1, 6, 'جومر یوځل بیا امیدواره شوه او دا ځل یې یوه لور پیدا شوه. څښتن هوشع ته وویل: «په هغې باندې لوروحامه یعنې ‹په چا باندې چې رحم نه وي شوی› نوم کېږده، ځکه چې زه به نور د اسراییلو په خلکو باندې رحم نه کوم او نه به هغوی وبخښم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_6.mp3', '', 1761754199, 1761754199),
(38293, 'Hosea 1:7', 'Hosea', 1, 7, 'خو زه به د یهودا په خلکو باندې رحم وکړم. زه څښتن چې د هغوی خدای یم، نو هغوی به وژغورم، خو زه به دا کار د جنګ، تورو، لیندو، غشو، اسونو یا په اسونو باندې په سپرو خلکو باندې ونه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_7.mp3', '', 1761754199, 1761754199),
(38294, 'Hosea 1:8', 'Hosea', 1, 8, 'کله چې جومر خپله لور لوروحامه له تي نه بېله کړله، نو هغه بیا امیدواره شوه او بل زوی یې پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_8.mp3', '', 1761754199, 1761754199),
(38295, 'Hosea 1:9', 'Hosea', 1, 9, 'څښتن هوشع ته وویل: «په هغه باندې لوعمي یعنې ‹زما قوم نه دی› نوم کېږده، ځکه چې د اسراییلو خلک زما خلک نه دي او زه د هغوی خدای نه یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_9.mp3', '', 1761754199, 1761754199),
(38296, 'Hosea 1:10', 'Hosea', 1, 10, 'خو د اسراییلو خلک به د سیند د شګو په شان دومره زیات شي چې څوک به یې شمېرلی نه شي. اوس خدای هغوی ته وایي: «تاسو زما قوم نه یئ» خو یوه ورځ به راشي چې هغه به ورته ووایي: «تاسو د ژوندي خدای اولادونه یئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_10.mp3', '', 1761754199, 1761754199),
(38297, 'Hosea 1:11', 'Hosea', 1, 11, 'نو د یهودا او اسراییلو خلک به بیا سره یوځای شي. هغوی به د خپل ځان دپاره یو مشر وټاکي او یوځل بیا به د هغوی شمېر په خپل وطن کې زیات او نېکمرغه شي. هو، دا به د یزرعیل د سیمې دپاره یوه لویه ورځ وي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea1_verse_11.mp3', '', 1761754199, 1761754199),
(38298, 'Leviticus 11:1', 'Leviticus', 11, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_1.mp3', '', 1761754199, 1761754199),
(38299, 'Leviticus 11:2', 'Leviticus', 11, 2, '«اسراییلیانو ته ووایئ چې د ټولو حیواناتو له جملې څخه چې په ځمکه باندې ژوند کوي، یعنې هغه حیوانات چې غوښه یې خوړلی شئ، هغه دا دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_2.mp3', '', 1761754199, 1761754199),
(38300, 'Leviticus 11:3', 'Leviticus', 11, 3, 'هر حیوان چې خلاص سوم ولري او شخوند وهونکی هم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_3.mp3', '', 1761754199, 1761754199),
(38301, 'Leviticus 11:4', 'Leviticus', 11, 4, 'خو داسې حیوانات شته چې یوازې شخوند وهونکي دي یا یوازې خلاص سوم لري، خو تاسو باید د هغو غوښه ونه خورئ. لکه اوښ، که څه هم هغه شخوند وهونکی دی، خو خلاص سوم نه لري. دا ستاسو دپاره ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_4.mp3', '', 1761754199, 1761754199),
(38302, 'Leviticus 11:5', 'Leviticus', 11, 5, 'غرنۍ سویه، که څه هم هغه شخوند وهونکې ده خو خلاص سوم نه لري، دا ستاسو دپاره ناپاکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_5.mp3', '', 1761754199, 1761754199),
(38303, 'Leviticus 11:6', 'Leviticus', 11, 6, 'سویه که څه هم شخوند وهونکې ده، خو خلاص سوم نه لري. دا ستاسو دپاره ناپاکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_6.mp3', '', 1761754199, 1761754199),
(38304, 'Leviticus 11:7', 'Leviticus', 11, 7, 'د خوګ غوښه مه خورئ. هغه باید ناپاک وګڼل شي. هغه خلاص سومان لري، خو شخوند وهونکی نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_7.mp3', '', 1761754199, 1761754199),
(38305, 'Leviticus 11:8', 'Leviticus', 11, 8, 'تاسو باید د دې حیواناتو غوښه ونه خورئ او مه د هغو مړو ته لاس وروړئ، دا ستاسو دپاره ناپاک دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_8.mp3', '', 1761754199, 1761754199),
(38306, 'Leviticus 11:9', 'Leviticus', 11, 9, 'تاسو کولای شئ هر ډول ماهیان چې وزرونه او پتري ولري وخورئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_9.mp3', '', 1761754199, 1761754199),
(38307, 'Leviticus 11:10', 'Leviticus', 11, 10, 'خو هر حیوان چې په اوبو کې ژوند کوي او وزرونه او پتري نه لري، باید غوښه یې ونه خوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_10.mp3', '', 1761754199, 1761754199),
(38308, 'Leviticus 11:11', 'Leviticus', 11, 11, 'داسې حیوانات باید حرام وګڼل شي. تاسو باید د هغو غوښه ونه خورئ او حتی مړو ته یې لاس هم مه وروړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_11.mp3', '', 1761754199, 1761754199),
(38309, 'Leviticus 11:12', 'Leviticus', 11, 12, 'هر شی چې په اوبو کې ژوند کوي او وزرونه او پتري ونه لري، باید ونه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_12.mp3', '', 1761754199, 1761754199),
(38310, 'Leviticus 11:20', 'Leviticus', 11, 20, 'ټول وزر لرونکي حشرات حرام دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_20.mp3', '', 1761754199, 1761754199);